# Adaptive rejection sampling (Gilks and Wild, 1992)
# The supplied density need not be normalized, but its log-density must be concave.
sample_count <- 1000L

.ars_log_density <- function(density_function) {
  if (is.function(density_function)) {
    fun <- function(x) density_function(x)
  } else if (is.language(density_function) || is.expression(density_function)) {
    expr <- if (is.expression(density_function)) density_function[[1L]] else density_function
    fun <- function(x) eval(expr, envir = list(x = x), enclos = parent.frame())
  } else stop("density_function must be a function or an expression")
  function(x) {
    z <- tryCatch(fun(x), error = function(e) stop("density_function failed: ", e$message))
    if (length(z) != length(x)) stop("density_function must be vectorized")
    z <- as.numeric(z)
    if (any(is.nan(z)) || any(z < 0, na.rm = TRUE) || any(is.infinite(z) & z > 0))
      stop("density_function must return finite non-negative densities")
    ans <- rep(-Inf, length(z)); ok <- z > 0 & is.finite(z)
    ans[ok] <- log(z[ok]); ans
  }
}

.ars_initial_points <- function(domain, logf) {
  a <- domain[1]; b <- domain[2]
  if (is.finite(a) && is.finite(b)) return(seq(a, b, length.out = 8L))
  if (is.finite(a)) return(a + c(.1, .5, 1, 2, 4, 8, 16))
  if (is.finite(b)) return(b - c(.1, .5, 1, 2, 4, 8, 16))
  c(-8, -4, -2, -1, 0, 1, 2, 4, 8)
}

.ars_check_concavity <- function(x, y, tolerance = 2e-5) {
  keep <- is.finite(y)
  x <- x[keep]; y <- y[keep]
  if (length(x) < 3L) stop("density is zero at too many initial points")
  s <- diff(y) / diff(x)
  if (any(diff(s) > tolerance * (1 + max(abs(s)))))
    stop("density appears non-log-concave (increasing secant slopes detected)")
  invisible(TRUE)
}

.ars_slopes <- function(x, y, logf) {
  k <- length(x); s <- numeric(k)
  # Numerical derivatives are used because the public API accepts densities only.
  for (i in seq_len(k)) {
    h <- max(1e-5, 1e-4 * (1 + abs(x[i])))
    lo <- x[i] - h; hi <- x[i] + h
    if (!is.finite(lo) || lo <= -Inf) lo <- x[i] - h/2
    if (!is.finite(hi) || hi >= Inf) hi <- x[i] + h/2
    yl <- logf(lo); yh <- logf(hi)
    s[i] <- if (is.finite(yl) && is.finite(yh)) (yh - yl)/(hi-lo) else
      if (i == 1L) (y[2]-y[1])/(x[2]-x[1]) else if (i == k) (y[k]-y[k-1])/(x[k]-x[k-1]) else (y[i+1]-y[i-1])/(x[i+1]-x[i-1])
  }
  # A concave log density has non-increasing derivatives. Small numerical noise is
  # removed; this also makes intersections well-defined.
  for (i in 2:k) s[i] <- min(s[i], s[i-1] - 1e-10)
  s
}

.ars_hull <- function(x, y, s, domain) {
  k <- length(x); z <- rep(NA_real_, k + 1L); z[1] <- domain[1]; z[k+1] <- domain[2]
  for (i in 2:k) {
    den <- s[i-1] - s[i]
    z[i] <- if (abs(den) < 1e-12) (x[i-1]+x[i])/2 else
      (y[i] - s[i]*x[i] - y[i-1] + s[i-1]*x[i-1])/den
  }
  if (any(diff(z) <= 0, na.rm = TRUE)) stop("unable to construct a valid ARS hull")
  list(z=z, x=x, y=y, s=s)
}

.ars_integrals <- function(hull) {
  x <- hull$x; y <- hull$y; s <- hull$s; z <- hull$z; k <- length(x)
  out <- numeric(k)
  for (i in seq_len(k)) {
    l <- z[i]; r <- z[i+1]; c <- y[i] - s[i]*x[i]
    # Integral of exp(c + slope*x), evaluated stably enough for ordinary densities.
    if (is.infinite(l) && s[i] <= 0 || is.infinite(r) && s[i] >= 0)
      out[i] <- Inf
    else if (abs(s[i]) < 1e-10) out[i] <- exp(c) * (r-l)
    else out[i] <- exp(c) * (exp(s[i]*r)-exp(s[i]*l))/s[i]
  }
  if (any(!is.finite(out)) || sum(out) <= 0) stop("ARS envelope is not integrable; check tail behavior")
  out
}

.ars_draw_hull <- function(hull, weights) {
  i <- sample.int(length(weights), 1L, prob = weights)
  l <- hull$z[i]; r <- hull$z[i+1]; s <- hull$s[i]; c <- hull$y[i] - s*hull$x[i]
  u <- runif(1)
  if (abs(s) < 1e-10) l + u*(r-l) else log(exp(s*l) + u*(exp(s*r)-exp(s*l)))/s
}

ars <- function(density_function, domain, n = sample_count) {
  if (length(domain) != 2L || anyNA(domain) || domain[1] >= domain[2] ||
      domain[1] == Inf || domain[2] == -Inf) stop("domain must be c(lower, upper), lower < upper")
  if (length(n) != 1L || !is.numeric(n) || !is.finite(n) || n < 0 || n != as.integer(n))
    stop("n must be one non-negative integer")
  n <- as.integer(n); if (!n) return(numeric(0))
  logf <- .ars_log_density(density_function)
  xx <- .ars_initial_points(domain, logf); xx <- sort(unique(xx[xx > domain[1] & xx < domain[2]]))
  yy <- logf(xx)
  .ars_check_concavity(xx, yy)
  if (any(!is.finite(yy))) stop("density must be positive at initial points")
  ans <- numeric(n); accepted <- 0L; iter <- 0L
  while (accepted < n) {
    iter <- iter + 1L; if (iter > 100000L) stop("ARS exceeded iteration limit")
    s <- .ars_slopes(xx, yy, logf); h <- .ars_hull(xx, yy, s, domain); w <- .ars_integrals(h)
    q <- .ars_draw_hull(h, w); lq <- yy[which.min(abs(xx-q))] # replaced below by hull formula
    j <- findInterval(q, h$z, all.inside = TRUE); lq <- h$y[j] + h$s[j]*(q-h$x[j])
    lf <- logf(q)
    if (!is.finite(lf)) next
    # Violation means the numerical tangent is not an upper hull: this is an
    # important safety check rather than silently returning biased samples.
    if (lf > lq + 1e-5) stop("non-log-concave density or inadequate numerical tangent detected")
    if (log(runif(1)) <= lf-lq) { accepted <- accepted + 1L; ans[accepted] <- q }
    # Adapt after every accepted or rejected proposal.
    if (all(abs(xx-q) > 1e-10)) {
      xx <- sort(c(xx, q)); yy <- logf(xx); .ars_check_concavity(xx, yy)
    }
  }
  ans
}

# Formal stochastic tests; writes a reproducible-sized example file.
test <- function() {
  set.seed(2024)
  z <- ars(function(x) dnorm(x), c(-Inf, Inf), 5000)
  m <- mean(z); sdv <- sd(z); ok <- abs(m) < .10 && abs(sdv-1) < .10
  cat(sprintf("NORMAL_SHAPE: %s (mean=%.4f, sd=%.4f)\n", ifelse(ok,"PASS","FAIL"),m,sdv))
  write.table(z, "/app/normal_samples.txt", row.names=FALSE, col.names=FALSE)
  e <- ars(function(x) dexp(x), c(0, Inf), 5000)
  m <- mean(e); sdv <- sd(e); ok <- abs(m-1) < .10 && abs(sdv-1) < .10
  cat(sprintf("EXPONENTIAL_SHAPE: %s (mean=%.4f, sd=%.4f)\n", ifelse(ok,"PASS","FAIL"),m,sdv))
  bad <- tryCatch({ ars(function(x) 1 + 0.8*cos(3*x), c(-pi,pi), 10); FALSE }, error=function(e) TRUE)
  cat(sprintf("NON_LOG_CONCAVE_REJECTION: %s\n", ifelse(bad,"PASS","FAIL")))
  invisible(all(c(abs(mean(z)) < .10, abs(mean(e)-1) < .10, bad)))
}

